async function relationalQuery(
  websiteId: string,
  filters: QueryFilters
): Promise<WebsiteStats[]> {
  // Expect filters to include at least: startDate, endDate, eventType
  const { startDate, endDate, eventType, ...rest } = filters;

  // Build extra filter conditions from remaining keys, e.g. { country: 'US', device: 'mobile' }
  const extraFilters = Object.entries(rest)
    .map(([k, v]) => {
      const val = typeof v === 'string' ? `'${v}'` : v;
      return `AND ${k} = ${val}`;
    })
    .join(' ');

  // Inner aggregation per session/visit
  // c = count of events in the session/visit
  // min_time / max_time = window of activity
  // We then compute:
  // - pageviews: sum of c
  // - visitors: sum of distinct visitors (approximated via count distinct user_id per session/visit)
  // - visits: count of distinct visit_id
  // - bounces: count of sessions with exactly 1 event (c = 1)
  // - totaltime: sum(max_time - min_time)
  const sql = `
    SELECT
      SUM(t.c) AS pageviews,
      SUM(t.visitors) AS visitors,
      SUM(t.visits) AS visits,
      SUM(CASE WHEN t.c = 1 THEN 1 ELSE 0 END) AS bounces,
      SUM(t.totaltime) AS totaltime
    FROM (
      SELECT
        session_id,
        visit_id,
        COUNT(*) AS c,
        COUNT(DISTINCT user_id) AS visitors,
        COUNT(DISTINCT visit_id) AS visits,
        MIN(created_at) AS min_time,
        MAX(created_at) AS max_time,
        TIMESTAMP_DIFF(MAX(created_at), MIN(created_at), SECOND) AS totaltime
      FROM website_event
      WHERE website_id = '${websiteId}'
        AND created_at BETWEEN '${startDate}' AND '${endDate}'
        AND event_type = ${eventType}
        ${extraFilters}
      GROUP BY session_id, visit_id
    ) AS t;
  `;

  const result = await prisma.$queryRaw<{
    pageviews: string | number;
    visitors: string | number;
    visits: string | number;
    bounces: string | number;
    totaltime: string | number;
  }>(sql);

  // Normalize to numbers and return as WebsiteStats[]
  return (Array.isArray(result) ? result : [result]).map(n => ({
    pageviews: Number(n.pageviews),
    visitors: Number(n.visitors),
    visits: Number(n.visits),
    bounces: Number(n.bounces),
    totaltime: Number(n.totaltime),
  }));
}

